"""Generated by Riffle from a 2-qubit circuit with 1 work qubit."""
from guppylang import guppy
from guppylang.std.quantum import qubit, measure, discard, cz, h, toffoli, x, z
from guppylang.std.builtins import result


@guppy
def main() -> None:
    q0 = qubit(); q1 = qubit(); w0 = qubit()
    h(q0)  # s0
    h(q1)  # s1
    toffoli(q0, q1, w0)  # both
    z(w0)  # mark
    toffoli(q0, q1, w0)  # cleanup, added by Riffle
    h(q0)  # h0
    h(q1)  # h1
    x(q0)  # x0
    x(q1)  # x1
    cz(q0, q1)  # mirror
    x(q0)  # u0
    x(q1)  # u1
    h(q0)  # out0
    h(q1)  # out1
    result("c0", measure(q0).read())
    result("c1", measure(q1).read())
    discard(w0)
